"""Paired reference pixels and draw submission timing for the static UV renderer.
The old CPU implementation is served only as a Playwright route fixture.
Run: UNITY_URL=http://127.0.0.1:3483 python3 test/baccarat-renderer_browser.py
"""
import json, os
from pathlib import Path
from playwright.sync_api import sync_playwright
BASELINE = "import {cardMesh} from './card-curl.js';\nimport {cardImage as image} from './card-images.js';\nfunction shader(gl,type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('CARD_SHADER');return s;}\n// One tiny local WebGL surface, reused across cards. The rest of the game is DOM.\nexport class CurlRenderer{\n constructor(canvas,front,back){\n  this.canvas=canvas;this.progress=0;this.disposed=false;const gl=this.gl=canvas.getContext('webgl',{alpha:true,antialias:true,premultipliedAlpha:true,preserveDrawingBuffer:true,powerPreference:'low-power'});if(!gl){this.ready=Promise.reject(Error('CARD_GRAPHICS'));return;}\n  this.program=gl.createProgram();const vs=shader(gl,gl.VERTEX_SHADER,`attribute vec3 position;attribute vec2 uv;attribute vec2 material;uniform vec2 scale;uniform float peek;varying vec2 tex;varying vec2 surface;void main(){float angle=.16;float y=position.y*cos(angle)-(position.z-.12)*sin(angle);float z=position.y*sin(angle)+(position.z-.12)*cos(angle)+position.x*.035;float approach=1.+.02*smoothstep(.7,1.,peek);gl_Position=vec4((position.x+(position.z-.12)*.045)*scale.x*approach,-y*scale.y*approach,-z*.2,1.-z/4.);tex=uv;surface=material;}`),fs=shader(gl,gl.FRAGMENT_SHADER,`precision mediump float;uniform sampler2D face;uniform sampler2D reverse;varying vec2 tex;varying vec2 surface;void main(){vec4 c=gl_FrontFacing?texture2D(reverse,tex):texture2D(face,vec2(tex.x,1.-tex.y));if(c.a<.02)discard;float band=max(0.,1.-abs(tex.x-.32)*1.5);band*=band;band*=band;float sheen=band*band*(1.-surface.y)*.16;vec3 paper=c.rgb*(.78+.22*surface.y)+vec3(1.,.94,.80)*sheen;gl_FragColor=vec4(paper,c.a);}`);\n  gl.attachShader(this.program,vs);gl.attachShader(this.program,fs);gl.linkProgram(this.program);gl.deleteShader(vs);gl.deleteShader(fs);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error('CARD_PROGRAM');gl.useProgram(this.program);this.buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);\n  for(const[name,size,offset]of[['position',3,0],['uv',2,12],['material',2,20]]){const loc=gl.getAttribLocation(this.program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,size,gl.FLOAT,false,28,offset);}\n  gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);gl.disable(gl.CULL_FACE);gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA,gl.ONE,gl.ONE_MINUS_SRC_ALPHA);this.textures=[];\n  this.ready=Promise.all([image(front),image(back)]).then(images=>{if(this.disposed)return;gl.useProgram(this.program);for(const[i,img]of images.entries()){const t=gl.createTexture();this.textures.push(t);gl.activeTexture(gl.TEXTURE0+i);gl.bindTexture(gl.TEXTURE_2D,t);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,img);for(const param of [gl.TEXTURE_MIN_FILTER,gl.TEXTURE_MAG_FILTER])gl.texParameteri(gl.TEXTURE_2D,param,gl.LINEAR);for(const param of [gl.TEXTURE_WRAP_S,gl.TEXTURE_WRAP_T])gl.texParameteri(gl.TEXTURE_2D,param,gl.CLAMP_TO_EDGE);gl.uniform1i(gl.getUniformLocation(this.program,i?'reverse':'face'),i);}canvas.dataset.renderer='webgl';this.loaded=true;this.draw(this.progress);});\n  this.resize=new ResizeObserver(()=>this.draw(this.progress));this.resize.observe(canvas);\n }\n draw(p,options=this.options||{}){this.options=options;this.progress=p;if(!this.loaded||this.disposed||this.gl.isContextLost())return;const c=this.canvas,rect=c.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1),w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(!w||!h)return;if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const gl=this.gl,mesh=cardMesh(p,8,80,options),data=[];for(const tri of mesh.triangles)for(const i of tri.indices){const v=mesh.vertices[i];data.push(v.x,v.y,v.z,v.u,v.v,tri.side==='face'?1:0,.68+.32*Math.abs(Math.cos(v.angle-.3)));}gl.useProgram(this.program);gl.bindBuffer(gl.ARRAY_BUFFER,this.buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(data),gl.DYNAMIC_DRAW);const scale=Math.min(w/1.08,h/1.52);gl.uniform1f(gl.getUniformLocation(this.program,'peek'),p);gl.uniform2f(gl.getUniformLocation(this.program,'scale'),scale*2/w,scale*2/h);gl.viewport(0,0,w,h);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.drawArrays(gl.TRIANGLES,0,data.length/7);\n  const projected=mesh.vertices.map(v=>{const y=v.y*Math.cos(.16)-(v.z-.12)*Math.sin(.16),z=v.y*Math.sin(.16)+(v.z-.12)*Math.cos(.16)+v.x*.035,k=(1+.02*(p>.7?Math.min(1,(p-.7)/.3):0))/(1-z/4);return{x:w/2+(v.x+(v.z-.12)*.045)*scale*k,y:h/2+y*scale*k};});const left=Math.min(...projected.map(v=>v.x))/dpr,right=Math.max(...projected.map(v=>v.x))/dpr,bottom=Math.max(...projected.map(v=>v.y))/dpr;c.dataset.cardWidth=right-left;if(p<.02&&c.parentElement){c.parentElement.style.setProperty('--card-left',left+'px');c.parentElement.style.setProperty('--card-right',right+'px');c.parentElement.style.setProperty('--card-bottom',bottom+'px');}\n\n }\n dispose(){this.disposed=true;this.resize?.disconnect();if(!this.gl)return;for(const t of this.textures||[])this.gl.deleteTexture(t);if(this.buffer)this.gl.deleteBuffer(this.buffer);if(this.program)this.gl.deleteProgram(this.program);}\n}\n"
base=os.environ.get('UNITY_URL','http://127.0.0.1:3483')
out=Path('/tmp/baccarat-renderer-proof');out.mkdir(exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':700,'height':500},device_scale_factor=1)
 page.route('**/baccarat/renderer-reference.js',lambda route:route.fulfill(status=200,content_type='text/javascript',body=BASELINE))
 page.goto(base+'/baccarat/index.html')
 result=page.evaluate("""async()=>{
 const [{CurlRenderer:Reference},{CurlRenderer:Current},{FACES,BACK}]=await Promise.all([import('./renderer-reference.js'),import('./curl-renderer.js'),import('./card-data.js')]);
 document.body.innerHTML='<div style="display:flex"><canvas style="width:320px;height:460px"></canvas><canvas style="width:320px;height:460px"></canvas></div>';
 const canvases=[...document.querySelectorAll('canvas')],url=s=>'data:image/svg+xml,'+encodeURIComponent(s),renderers=[new Reference(canvases[0],url(FACES[0]),url(BACK)),new Current(canvases[1],url(FACES[0]),url(BACK))];await Promise.all(renderers.map(r=>r.ready));
 const states=[];for(const progress of [0,.25,.5,.75,1])for(const gripX of [-.7,0,.7]){
 const pixels=renderers.map(r=>{r.draw(progress,{gripX});const gl=r.gl,a=new Uint8Array(r.canvas.width*r.canvas.height*4);gl.readPixels(0,0,r.canvas.width,r.canvas.height,gl.RGBA,gl.UNSIGNED_BYTE,a);return a;});
 let total=0,changed=0,max=0;for(let i=0;i<pixels[0].length;i++){const d=Math.abs(pixels[0][i]-pixels[1][i]);total+=d;max=Math.max(max,d);if(d>4)changed++;}
 states.push({progress,gripX,meanAbsoluteChannelError:total/pixels[0].length,channelsOver4:changed/pixels[0].length,maxError:max,width: +canvases[1].dataset.cardWidth});}
 const timings=[];for(let trial=0;trial<5;trial++)for(const [i,r] of renderers.entries()){const start=performance.now();for(let n=0;n<120;n++)r.draw((n%101)/100,{gripX:.7});r.gl.finish();timings.push({trial,renderer:i?'static':'reference',ms:performance.now()-start});}
 renderers.forEach(r=>r.draw(.5,{gripX:.7}));window.proofRenderers=renderers;return{states,timings};
 }""")
 page.screenshot(path=str(out/'paired.png'))
 # Raster differences from float shader arithmetic must stay visually negligible.
 assert all(s['meanAbsoluteChannelError']<.5 and s['channelsOver4']<.005 for s in result['states']),result['states']
 assert all(s['width']>=320*.78 for s in result['states'] if s['progress']==0)
 page.evaluate('proofRenderers.forEach(r=>r.dispose())')
 (out/'proof.json').write_text(json.dumps(result,indent=2))
 browser.close();print(json.dumps(result,indent=2))
